// Domain classification
const domains = {
    '09-dev-tools': ['1password','clawhub','coding-agent','diagram-maker',
        'eightctl','gemini','gh-issues','gog','healthcheck','mcporter',
        'model-usage','nano-pdf','node-connect','node-inspect-debugger',
        'openai-whisper','openai-whisper-api','oracle','ordercli',
        'peekaboo','python-debugpy','sag','session-logs','skill-creator',
        'spike','taskflow','taskflow-inbox-triage','video-frames','xurl'],
    '06-frontend-ui': ['apple-notes','apple-reminders','bear-notes','blogwatcher',
        'blucli','camsnap','gifgrep','goplaces','himalaya','imsg',
        'meme-maker','obsidian','openhue','sherpa-onnx-tts','songsee',
        'sonoscli','spotify-player','summarize','things-mac','tmux',
        'trello','weather'],
    '02-skill-ecosystem': ['notion']
